import dayjs from"dayjs";import customParseFormat from"dayjs/plugin/customParseFormat.js";import"dayjs/locale/zh-cn.js";dayjs.locale("zh-cn"),dayjs.extend(customParseFormat);export function getFormatDate(t){return t?dayjs().format(t):t}export function strToTimestamp(t){return new Date(t).getTime()}export function timestampToStr(t,r){return dayjs(t).format(r)}export function validDateFormat(t,r){const a=dayjs(t,r,!0);return!(!a.isValid()||a.format(r)!==t)&&a}